//! File-manager integration: Nautilus scripts, Dolphin service menu, XDG Templates symlinks.

use anyhow::{Context, Result};
use std::collections::HashSet;
use std::fs;
use std::io::Read;
use std::os::unix::fs::PermissionsExt;
use std::path::{Path, PathBuf};
use tracing::{info, warn};

use crate::NewPlusConfig;
use crate::templates::{Template, list_templates};

/// Marker written into every generated file; only files containing it are ever deleted.
pub const MARKER: &str = "Generated by my-power-toys New+ (mpt-new-plus); do not edit";

const OPEN_TEMPLATES_LABEL: &str = "Open templates folder";

fn data_home() -> Option<PathBuf> {
    dirs::data_dir()
}

fn nautilus_dir() -> Option<PathBuf> {
    data_home().map(|d| d.join("nautilus/scripts/New+"))
}

fn dolphin_file() -> Option<PathBuf> {
    data_home().map(|d| d.join("kio/servicemenus/mpt-new-plus.desktop"))
}

fn xdg_manifest() -> Option<PathBuf> {
    data_home().map(|d| d.join("my-power-toys/new-plus-xdg-links.txt"))
}

/// Regenerate everything according to `config` (removes integration that is disabled).
pub fn apply(config: &NewPlusConfig, bin: &Path) -> Result<()> {
    remove_file_manager();
    if config.context_menu {
        let dir = config.templates_dir();
        let templates = list_templates(&dir).unwrap_or_else(|e| {
            warn!("New+: {e:#}");
            Vec::new()
        });
        if let Err(e) = write_nautilus(config, &templates, &dir, bin) {
            warn!("New+: failed to write Nautilus scripts: {e:#}");
        }
        if let Err(e) = write_dolphin(config, &templates, &dir, bin) {
            warn!("New+: failed to write Dolphin service menu: {e:#}");
        }
    }
    remove_xdg_links();
    if config.sync_xdg_templates
        && let Err(e) = sync_xdg(config)
    {
        warn!("New+: failed to sync XDG Templates: {e:#}");
    }
    Ok(())
}

/// Remove all generated integration files.
pub fn remove_all() {
    remove_file_manager();
    remove_xdg_links();
}

fn is_marked(path: &Path) -> bool {
    let Ok(mut f) = fs::File::open(path) else {
        return false;
    };
    let mut buf = vec![0u8; 512];
    let n = f.read(&mut buf).unwrap_or(0);
    String::from_utf8_lossy(&buf[..n]).contains(MARKER)
}

fn remove_file_manager() {
    if let Some(dir) = nautilus_dir()
        && let Ok(entries) = fs::read_dir(&dir)
    {
        for e in entries.flatten() {
            let p = e.path();
            if p.is_file() && is_marked(&p) {
                let _ = fs::remove_file(&p);
            }
        }
        // Only succeeds when empty.
        let _ = fs::remove_dir(&dir);
    }
    if let Some(f) = dolphin_file()
        && is_marked(&f)
    {
        let _ = fs::remove_file(&f);
    }
}

fn write_executable(path: &Path, content: &str) -> Result<()> {
    fs::write(path, content).with_context(|| format!("failed to write {}", path.display()))?;
    fs::set_permissions(path, fs::Permissions::from_mode(0o755))?;
    Ok(())
}

/// Quote for POSIX sh.
pub fn sh_quote(s: &str) -> String {
    format!("'{}'", s.replace('\'', "'\\''"))
}

/// Quote one argument for a desktop-entry `Exec=` value (exec quoting + string escaping + `%%`).
pub fn desktop_exec_arg(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' | '`' | '$' => {
                out.push_str("\\\\");
                out.push(c);
            }
            '\\' => out.push_str("\\\\\\\\"),
            '%' => out.push_str("%%"),
            '\n' | '\r' => out.push(' '),
            _ => out.push(c),
        }
    }
    out.push('"');
    out
}

fn desktop_value(s: &str) -> String {
    s.replace('\\', "\\\\").replace(['\n', '\r'], " ")
}

/// Unique, non-empty display names (appends " (2)" etc. on duplicates).
fn unique_labels(config: &NewPlusConfig, templates: &[Template]) -> Vec<String> {
    let mut seen = HashSet::new();
    seen.insert(OPEN_TEMPLATES_LABEL.to_string());
    templates
        .iter()
        .map(|t| {
            let mut base = t.display_name(config);
            if base.trim().is_empty() {
                base = t.file_name.clone();
            }
            let mut label = base.clone();
            let mut n = 2;
            while !seen.insert(label.clone()) {
                label = format!("{base} ({n})");
                n += 1;
            }
            label
        })
        .collect()
}

fn write_nautilus(
    config: &NewPlusConfig,
    templates: &[Template],
    tpl_dir: &Path,
    bin: &Path,
) -> Result<()> {
    let dir = nautilus_dir().context("no data dir")?;
    fs::create_dir_all(&dir)?;
    let bin = sh_quote(&bin.to_string_lossy());
    for (t, label) in templates.iter().zip(unique_labels(config, templates)) {
        let path = dir.join(&label);
        if path.exists() && !is_marked(&path) {
            warn!("New+: not overwriting user script {}", path.display());
            continue;
        }
        let script = format!(
            "#!/bin/sh\n# {MARKER}\nexec {bin} create {}\n",
            sh_quote(&t.path.to_string_lossy())
        );
        write_executable(&path, &script)?;
    }
    let open = dir.join(OPEN_TEMPLATES_LABEL);
    if !open.exists() || is_marked(&open) {
        let script = format!(
            "#!/bin/sh\n# {MARKER}\nexec xdg-open {}\n",
            sh_quote(&tpl_dir.to_string_lossy())
        );
        write_executable(&open, &script)?;
    }
    info!("New+: wrote Nautilus scripts to {}", dir.display());
    Ok(())
}

fn write_dolphin(
    config: &NewPlusConfig,
    templates: &[Template],
    tpl_dir: &Path,
    bin: &Path,
) -> Result<()> {
    let file = dolphin_file().context("no data dir")?;
    if file.exists() && !is_marked(&file) {
        warn!("New+: not overwriting user file {}", file.display());
        return Ok(());
    }
    if let Some(parent) = file.parent() {
        fs::create_dir_all(parent)?;
    }
    let bin = desktop_exec_arg(&bin.to_string_lossy());
    let mut actions: Vec<String> = (0..templates.len()).map(|i| format!("tpl{i}")).collect();
    actions.push("open_templates".into());

    let mut s = format!(
        "# {MARKER}\n[Desktop Entry]\nType=Service\nMimeType=inode/directory;\n\
         X-KDE-ServiceTypes=KonqPopupMenu/Plugin\nX-KDE-Submenu=New+\nIcon=document-new\n\
         Actions={};\n",
        actions.join(";")
    );
    for (i, (t, label)) in templates
        .iter()
        .zip(unique_labels(config, templates))
        .enumerate()
    {
        let icon = if t.is_dir {
            "folder-new"
        } else {
            "document-new"
        };
        s.push_str(&format!(
            "\n[Desktop Action tpl{i}]\nName={}\nIcon={icon}\nExec={bin} create {} %f\n",
            desktop_value(&label),
            desktop_exec_arg(&t.path.to_string_lossy())
        ));
    }
    s.push_str(&format!(
        "\n[Desktop Action open_templates]\nName={OPEN_TEMPLATES_LABEL}\nIcon=folder-templates\n\
         Exec=xdg-open {}\n",
        desktop_exec_arg(&tpl_dir.to_string_lossy())
    ));
    // Recent KDE versions require service menus to be executable.
    write_executable(&file, &s)?;
    info!("New+: wrote Dolphin service menu {}", file.display());
    Ok(())
}

/// XDG Templates directory (`xdg-user-dir TEMPLATES`, falling back to `~/Templates`).
pub fn xdg_templates_dir() -> Option<PathBuf> {
    let home = dirs::home_dir()?;
    let from_tool = std::process::Command::new("xdg-user-dir")
        .arg("TEMPLATES")
        .output()
        .ok()
        .filter(|o| o.status.success())
        .map(|o| PathBuf::from(String::from_utf8_lossy(&o.stdout).trim()))
        .filter(|p| !p.as_os_str().is_empty() && *p != home);
    Some(from_tool.unwrap_or_else(|| home.join("Templates")))
}

fn sync_xdg(config: &NewPlusConfig) -> Result<()> {
    let target = xdg_templates_dir().context("no home dir")?;
    fs::create_dir_all(&target)?;
    let templates = list_templates(&config.templates_dir())?;
    let mut created = Vec::new();
    for t in &templates {
        let link = target.join(t.target_name(config));
        if link.symlink_metadata().is_ok() {
            warn!("New+: {} already exists, not linking", link.display());
            continue;
        }
        match std::os::unix::fs::symlink(&t.path, &link) {
            Ok(()) => created.push(link),
            Err(e) => warn!("New+: failed to link {}: {e}", link.display()),
        }
    }
    let manifest = xdg_manifest().context("no data dir")?;
    if let Some(p) = manifest.parent() {
        fs::create_dir_all(p)?;
    }
    let list: Vec<String> = created
        .iter()
        .map(|p| p.to_string_lossy().into_owned())
        .collect();
    fs::write(&manifest, list.join("\n"))?;
    info!(
        "New+: linked {} templates into {}",
        created.len(),
        target.display()
    );
    Ok(())
}

/// Remove symlinks we created in the XDG Templates dir (tracked in a manifest).
fn remove_xdg_links() {
    let Some(manifest) = xdg_manifest() else {
        return;
    };
    let Ok(content) = fs::read_to_string(&manifest) else {
        return;
    };
    for line in content.lines().filter(|l| !l.is_empty()) {
        let p = Path::new(line);
        if p.symlink_metadata()
            .map(|m| m.file_type().is_symlink())
            .unwrap_or(false)
        {
            let _ = fs::remove_file(p);
        }
    }
    let _ = fs::remove_file(&manifest);
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn quoting() {
        assert_eq!(sh_quote("it's"), "'it'\\''s'");
        assert_eq!(desktop_exec_arg("a b"), "\"a b\"");
        assert_eq!(desktop_exec_arg("$x%"), "\"\\\\$x%%\"");
        assert_eq!(desktop_exec_arg("a\\b"), "\"a\\\\\\\\b\"");
    }
}
